// TesteRegressaoPrompt/Program.cs -- roda o golden set contra o texto do PR,
// bloqueia a promocao se a taxa de acerto cair abaixo do limiar. Reaproveita
// o cliente Bedrock do L81 (tema: streaming, retry, custo logado) -- aqui so
// a chamada e sincrona porque o teste precisa do texto completo para julgar.

using System.Text.Json;
using Amazon.BedrockRuntime;
using Amazon.BedrockRuntime.Model;

var caminhoPrompt = args.Length > 0 ? args[0] : "prompts/descricao-produto.txt";
var textoPrompt = await File.ReadAllTextAsync(caminhoPrompt);
var goldenSet = JsonSerializer.Deserialize<GoldenSet>(
    await File.ReadAllTextAsync("prompts/golden-set-descricao-produto.json"),
    new JsonSerializerOptions { PropertyNameCaseInsensitive = true })!;

using var bedrock = new AmazonBedrockRuntimeClient();
var resultados = new List<(string id, bool passou, string motivo)>();

foreach (var caso in goldenSet.Casos)
{
    var prompt = textoPrompt.Replace("{{produto}}", caso.Produto)
                              .Replace("{{atributos}}", caso.Atributos);

    // ID com prefixo de provedor, o mesmo padrao do L81 -- Haiku aqui porque
    // descricao de produto e uma tarefa barata, nao precisa do modelo mais caro.
    var resposta = await bedrock.InvokeModelAsync(new InvokeModelRequest
    {
        ModelId = "us.anthropic.claude-3-5-haiku-20241022-v1:0",
        ContentType = "application/json",
        Body = MontarCorpo(prompt),
    });
    var texto = ExtrairTexto(resposta);

    var faltouObrigatoria = caso.PalavrasObrigatorias
        .Where(p => !texto.Contains(p, StringComparison.OrdinalIgnoreCase)).ToList();
    var usouProibida = caso.PalavrasProibidas
        .Where(p => texto.Contains(p, StringComparison.OrdinalIgnoreCase)).ToList();
    var tamanhoOk = texto.Length >= caso.TamanhoMin && texto.Length <= caso.TamanhoMax;

    var passou = faltouObrigatoria.Count == 0 && usouProibida.Count == 0 && tamanhoOk;
    var motivos = new List<string>();
    if (faltouObrigatoria.Count > 0) motivos.Add($"faltou: {string.Join(',', faltouObrigatoria)}");
    if (usouProibida.Count > 0) motivos.Add($"usou proibida: {string.Join(',', usouProibida)}");
    if (!tamanhoOk) motivos.Add($"tamanho {texto.Length} fora de [{caso.TamanhoMin},{caso.TamanhoMax}]");

    resultados.Add((caso.Id, passou, passou ? "ok" : string.Join("; ", motivos)));
}

var passaram = resultados.Count(r => r.passou);
var taxa = passaram / (double)resultados.Count;
Console.WriteLine($"golden set: {passaram} de {resultados.Count} casos passaram ({taxa:P0})");
foreach (var r in resultados.Where(r => !r.passou))
    Console.WriteLine($"  FALHOU [{r.id}]: {r.motivo}");

if (taxa < goldenSet.LimiarAprovacao)
{
    Console.WriteLine($"taxa {taxa:P0} abaixo do limiar de {goldenSet.LimiarAprovacao:P0} -- pipeline bloqueado");
    Environment.Exit(1); // CodeBuild le este codigo de saida e falha o estagio
}

# pipeline-prompt.tf -- CodePipeline com fonte no GitHub via conexao, um
# estagio de teste bloqueante, e promocao condicionada ao resultado dele.

resource "aws_codestarconnections_connection" "github" {
  name          = "${var.projeto}-github"
  provider_type = "GitHub"
  # Apos aplicar, a conexao fica PENDING ate alguem autorizar no console --
  # o Terraform nao completa esse passo, e o pipeline nao dispara sem ele.
}

resource "aws_s3_bucket" "artefatos_pipeline" {
  bucket = "${var.projeto}-artefatos-prompt-pipeline"
}

resource "aws_cloudwatch_log_group" "teste_golden_set" {
  name              = "/aws/codebuild/${var.projeto}-teste-golden-set"
  retention_in_days = 30
}

resource "aws_codebuild_project" "teste_golden_set" {
  name         = "${var.projeto}-teste-golden-set"
  service_role = aws_iam_role.pipeline_prompt.arn

  environment {
    compute_type = "BUILD_GENERAL1_SMALL"
    image        = "aws/codebuild/standard:7.0"
    type         = "LINUX_CONTAINER"
    environment_variable {
      name  = "PROMPT_ID"
      value = aws_bedrockagent_prompt.descricao_produto.id
    }
  }

  logs_config {
    cloudwatch_logs {
      group_name = aws_cloudwatch_log_group.teste_golden_set.name
    }
  }

  source {
    type      = "CODEPIPELINE"
    buildspec = "buildspec.yml"
  }
  artifacts { type = "CODEPIPELINE" }
}

resource "aws_codepipeline" "prompt_descricao_produto" {
  name     = "${var.projeto}-prompt-descricao-produto"
  role_arn = aws_iam_role.pipeline_prompt.arn

  artifact_store {
    location = aws_s3_bucket.artefatos_pipeline.bucket
    type     = "S3"
  }

  stage {
    name = "Fonte"
    action {
      name             = "Github"
      category         = "Source"
      owner            = "AWS"
      provider         = "CodeStarSourceConnection"
      version          = "1"
      output_artifacts = ["codigo_fonte"]
      configuration = {
        ConnectionArn    = aws_codestarconnections_connection.github.arn
        FullRepositoryId = "cadencia/catalogo-prompts"
        BranchName       = "main"
      }
    }
  }

  # UNICO estagio que pode falhar sem consequencia visivel para produção: se
  # falhar aqui, PROMPT_VERSION nunca muda, e a versao anterior segue ativa.
  stage {
    name = "TestarGoldenSet"
    action {
      name             = "RodarGoldenSet"
      category         = "Build"
      owner            = "AWS"
      provider         = "CodeBuild"
      version          = "1"
      input_artifacts  = ["codigo_fonte"]
      output_artifacts = ["resultado_teste"]
      configuration    = { ProjectName = aws_codebuild_project.teste_golden_set.name }
    }
  }

  stage {
    name = "PromoverVersao"
    action {
      name            = "PublicarEApontar"
      category        = "Build"
      owner           = "AWS"
      provider        = "CodeBuild"
      version         = "1"
      input_artifacts = ["resultado_teste"]
      configuration   = { ProjectName = aws_codebuild_project.promover_versao.name }
      # So executa se o estagio anterior (TestarGoldenSet) tiver sucesso --
      # e o comportamento PADRAO do CodePipeline entre estagios sequenciais,
      # nao uma condicao extra que alguem precisa lembrar de configurar.
    }
  }
}

# parameter-store.tf -- ponte entre "versao testada" e "producao usa"

resource "aws_ssm_parameter" "prompt_version_producao" {
  name  = "/${var.projeto}/prompt/descricao-produto/versao-producao"
  type  = "String"
  value = "0" # placeholder -- o pipeline escreve o valor real apos a primeira promocao

  lifecycle {
    ignore_changes = [value] # o PIPELINE atualiza isto, nao o terraform apply
  }
}

// ResolvedorVersaoPrompt.cs -- le a versao ativa do Parameter Store com
// cache curto, e monta a chamada ao Bedrock fixada naquela versao. Reaproveita
// o ClienteBedrockStreaming do L81 (tema: primeira chamada com streaming e
// custo logado) -- so a resolucao da versao do prompt muda aqui.

public class ResolvedorVersaoPrompt
{
    private readonly IAmazonSimpleSystemsManagement _ssm;
    private string? _versaoEmCache;
    private DateTime _expiraEm = DateTime.MinValue;
    private static readonly TimeSpan TTL_CACHE = TimeSpan.FromSeconds(30);

    public async Task<string> VersaoAtivaAsync()
    {
        if (_versaoEmCache is not null && DateTime.UtcNow < _expiraEm)
            return _versaoEmCache;

        var resposta = await _ssm.GetParameterAsync(new GetParameterRequest
        {
            Name = "/cadencia/prompt/descricao-produto/versao-producao",
        });

        _versaoEmCache = resposta.Parameter.Value; // NUNCA "$LATEST" -- sempre um numero
        _expiraEm = DateTime.UtcNow.Add(TTL_CACHE);
        return _versaoEmCache;
    }
}

public class GeradorDescricao
{
    private readonly ResolvedorVersaoPrompt _versao;
    private readonly IAmazonBedrockAgent _bedrockAgent; // Prompt Management
    private readonly AmazonBedrockRuntimeClient _bedrockRuntime; // InvokeModel, do L81

    public async Task<string> GerarAsync(string produto, string atributos)
    {
        var versao = await _versao.VersaoAtivaAsync();

        // GetPromptVersion com numero FIXO -- e o que impede a API de herdar
        // uma edicao feita no console sem passar pelo pipeline.
        var promptResolvido = await _bedrockAgent.GetPromptAsync(new GetPromptRequest
        {
            PromptIdentifier = "descricao-produto",
            PromptVersion    = versao,
        });

        var texto = promptResolvido.Variants[0].TemplateConfiguration.Text.Text
            .Replace("{{produto}}", produto)
            .Replace("{{atributos}}", atributos);

        return await _bedrockRuntime.InvokeModelEColetarTextoAsync(texto, versao);
    }
}
